sys_script_include.script:
var assetRequestUtils = Class.create();
assetRequestUtils.prototype = {
    initialize: function() {
    },

	// Master funciton for Record Creation

	createAssetAndCI: function(current) {
        var confModelResponse = this.createConfModelRecord(current);
        var confItemResponse = this.createConfItemRecord(current, confModelResponse);
        var almHardwareResponse = this.createHardwareRecord(current, confModelResponse, confItemResponse);

        this.createConsumableRecord(current, confModelResponse, almHardwareResponse);

		var grCI = new GlideRecord('cmdb_ci');
        if (grCI.get(confItemResponse)) {
            grCI.asset = almHardwareResponse;
            grCI.update();
        }

        return confItemResponse; 
    },

	// Return Consumable Model Category sys_id

	getConsumableCategorySysId: function() {

        var grCat = new GlideRecord('cmdb_model_category');

        if (grCat.get('name', 'Consumable')) {
            return grCat.getUniqueValue();
        }

        return '';
    },

	// Create record in CMDB Model Tables

	createConfModelRecord : function (current) {
		var grConfModel = new GlideRecord('cmdb_model');

		grConfModel.initialize();

		grConfModel.manufacturer = current.requestor.company;
		grConfModel.name = current.consumables;
		grConfModel.cmdb_model_category = this.getConsumableCategorySysId();

		var result = grConfModel.insert();
		return result;
	},

	// Create record in CMDB CI Tables based on Asset Type

	createConfItemRecord : function (current, cmdb_model) {

		gs.info('IT Asset Call Create confirm item record fn');

		var tableName = current.getValue('type_of_asset').toString().toLowerCase();

		var cmdbTable = 'cmdb_ci_'+ tableName;

		var grConfItem = new GlideRecord(cmdbTable);
		grConfItem.initialize();

		grConfItem.name = current.number + '-' + current.consumables;
		grConfItem.company = current.requestor.company;
		grConfItem.manufacturer = current.requestor.company;
		grConfItem.assigned_to = current.requestor;
		grConfItem.department = current.requestor.department;
		// grConfItem.model_id = cmdb_model;

		var result = grConfItem.insert();

		return result;

	},

	// Create record in ALM Hardware Tables

	createHardwareRecord : function (current, cmdb_model, cmdb_asset) {
		var grHardware = new GlideRecord('alm_hardware');

		grHardware.initialize();

		grHardware.model_category = this.getConsumableCategorySysId();
		grHardware.assigned_to = current.requestor;
		grHardware.department = current.requestor.department;
		grHardware.location = current.requestor.location;
		grHardware.company = current.requestor.company;	
		grHardware.model = cmdb_model;
		grHardware.ci = cmdb_asset;
		grHardware.install_status = '2';

		var result = grHardware.insert();
		return result;
	},

	// Create record in ALM Consumable Tables

	createConsumableRecord : function (current, cmdb_model, alm_hardware) {
		var grConsumable = new GlideRecord('alm_consumable');

		grConsumable.initialize();

		grConsumable.model_category = this.getConsumableCategorySysId();
		grConsumable.model = cmdb_model;
		grConsumable.location = current.requestor.location;
		grConsumable.parent = alm_hardware;
		grConsumable.assigned_to = current.requestor;
		grConsumable.install_status = '2';

		var result = grConsumable.insert();
		return result;
	},

	// Update record in ALM Hardware and Consumable Record's

	updateAssetStatus : function (current) {
		var hwStatus = '';
		var consStatus = '';

		var reqStatus = current.getValue('status');

		if (reqStatus == 'dispatched') {
			hwStatus = '9';
			consStatus = '9';
		} else if (reqStatus == 'delivered') {
			hwStatus = '1';
			consStatus = '10';
		}

		// update state of Hardware record

		var hwSysId = '';

		var grHw = new GlideRecord('alm_hardware');

		if (grHw.get('ci', current.asset)) {
			hwSysId = grHw.getUniqueValue();
			grHw.install_status = hwStatus;
			if (hwStatus == '1') {
				grHw.assigned_to = current.requestor;
			}
			grHw.update();
		}

		// update state of Consumable record

		var grCons = new GlideRecord('alm_consumable');

		if (grCons.get('parent', hwSysId)) {
			grCons.install_status = consStatus;
			if (consStatus == '10') {
				grCons.assigned_to = current.requestor;
			}
			grCons.update();
		}

	},

	// Create Asset Request though Table API

	createAssetRequest: function(currentRecord) {

        var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action',
			'Create Record'
		);

		// r.setAuthenticationProfile('oauth2', 'b20991c72f1f87d0a94e2a7a6fa4e319');

        var payload = {
			"correlation_id": currentRecord.getValue('number'),
			"requestor": currentRecord.getValue('requestor'),
			"assignment_group": currentRecord.getValue('assignment_group'),
			"company": currentRecord.getValue('company'),
			"type_of_asset": currentRecord.getValue('type_of_asset'),
			"consumables": currentRecord.getValue('consumables'),
			"short_description": currentRecord.getValue('short_description'),
			"description": currentRecord.getValue('description'),
			"status": currentRecord.getValue('status'),
			"priority": currentRecord.getValue('priority')
		};

        r.setRequestHeader("Accept", "application/json");
        r.setRequestHeader("Content-Type", "application/json");
        r.setRequestBody(JSON.stringify(payload));

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        var parsedResponse = JSON.parse(responseBody);

		var notes = httpStatus + ' ' + responseBody;

		currentRecord.setValue('correlation_id', parsedResponse.result.number);
		currentRecord.work_notes = notes;

        var remoteSysId = parsedResponse.result.sys_id;

        if (remoteSysId) {

			// create mapping record in instnace A

            var grMap = new GlideRecord('x_2180885_it_ass_0_integration_map');
            grMap.initialize();
            grMap.setValue('local_sys_id', currentRecord.getUniqueValue());
            grMap.setValue('remote_sys_id', remoteSysId);
            grMap.setValue('target', 'Instance');
            grMap.insert();

			// create mapping record on instnace B

			var mapRest = new sn_ws.RESTMessageV2(
				'Instance-a Outbound Action',
				'Create Integration Map Record'
			);


			var mapPayload = {
				"local_sys_id": remoteSysId, 
				"remote_sys_id": currentRecord.getUniqueValue(),
				"target": "Instance"
			};

			mapRest.setRequestHeader("Accept", "application/json");
			mapRest.setRequestHeader("Content-Type", "application/json");
			mapRest.setRequestBody(JSON.stringify(mapPayload));

			mapRest.execute();

			// call attachment
			var attGr = new GlideRecord('sys_attachment');
			attGr.addQuery('table_name', currentRecord.getTableName());
			attGr.addQuery('table_sys_id', currentRecord.getUniqueValue());
			attGr.query();

			while (attGr.next()) {
				this.sendAttachment(attGr);
			}
        }
    },

	// Update Asset Request though Table API

	updateAssetRequest: function(currentRecord) {
        var targetSysId = '';
        var grMap = new GlideRecord('x_2180885_it_ass_0_integration_map');
        grMap.addQuery('local_sys_id', currentRecord.getUniqueValue());
        grMap.addQuery('target', 'Instance');
        grMap.setLimit(1);
        grMap.query();

        if (grMap.next()) {
            targetSysId = grMap.getValue('remote_sys_id');
        }

        var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action',
			'Update Record'
		);

        r.setStringParameter('target_sys_id', targetSysId);

        var payload = {
			"short_description": currentRecord.getValue('short_description'),
			"description": currentRecord.getValue('description'),
			"assigned_to": currentRecord.getValue('assigned_to'),
			"status": currentRecord.getValue('status'),
			"priority": currentRecord.getValue('priority')
		};

        r.setRequestHeader("Accept", "application/json");
        r.setRequestHeader("Content-Type", "application/json");
        r.setRequestBody(JSON.stringify(payload));

        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

		var notes = httpStatus + ' ' + responseBody;

		currentRecord.work_notes = notes;
    },

	// Delete Asset Request through Table API

    deleteAssetRequest: function(targetNumber) {

        var getReq = new sn_ws.RESTMessageV2(
            'Instance-a Outbound Action',
            'Retrive Record by Number'
        );

        getReq.setStringParameter(
            'target_number',
            targetNumber
        );

        var getResponse = getReq.execute();

        var result = JSON.parse(getResponse.getBody());

        var targetSysId = result.result[0].sys_id;


        var deleteReq = new sn_ws.RESTMessageV2(
            'Instance-a Outbound Action',
            'Delete Record'
        );

        deleteReq.setStringParameter(
            'target_sys_id',
            targetSysId
        );

        deleteReq.execute();
    },

	// Create Import Set Record using Import Set API

	createImportSetRecord: function(currentRecord) {
        var r = new sn_ws.RESTMessageV2(
            'Instance-a Outbound Action',
            'Create Import Set Record'
        );

        var payload = {
			"u_correlation_id": currentRecord.getValue('number'),
			"u_requestor": currentRecord.getValue('requestor'),
			"u_assignment_group": currentRecord.getDisplayValue('assignment_group'),
			"u_assigned_to": currentRecord.getValue('assigned_to'),
			"u_company": currentRecord.getValue('company'),
			"u_type_of_asset": currentRecord.getValue('type_of_asset'),
			"u_consumables": currentRecord.getValue('consumables'),
			"u_short_description": currentRecord.getValue('short_description'),
			"u_description": currentRecord.getValue('description'),
			"u_status": currentRecord.getValue('status'),
			"u_priority": currentRecord.getValue('priority')
		};

        r.setRequestHeader("Accept", "application/json");
        r.setRequestHeader("Content-Type", "application/json");
        r.setRequestBody(JSON.stringify(payload));

        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        var parsedResponse = JSON.parse(responseBody);

		var notes = httpStatus + ' ' + responseBody;

		currentRecord.work_notes = notes;

        var correlationId = parsedResponse["result"][0]["display_value"];

		currentRecord.setValue('correlation_id', correlationId);

    },

	// Create Asset Requst Record using Scripted REST API - 'CreateOrUpdateAssetRequest'

	createScriptedAssetRequest: function(currentRecord) {

		var payload = {
			"correlation_id": currentRecord.getValue('number'),
			"short_description": currentRecord.getValue('short_description'),
			"description": currentRecord.getValue('description'),
			"requestor": currentRecord.getValue('requestor'),
			"assignment_group": currentRecord.getValue('assignment_group'),
			"assigned_to": currentRecord.getValue('assigned_to'),
			"company": currentRecord.getValue('company'),
			"status": currentRecord.getValue('status'),
			"priority": currentRecord.getValue('priority'),
			"type_of_asset": currentRecord.getValue('type_of_asset'),
			"consumables": currentRecord.getValue('consumables')
		};

		var jsonBody = JSON.stringify(payload);

		var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action',
			'Create Scripted Asset Request'
		);

		r.setRequestHeader("Accept", "application/json");
		r.setRequestHeader("Content-Type", "application/json");
		r.setRequestBody(jsonBody);

		var response = r.executeAsync();
		var httpStatus = response.getStatusCode();
		var responseBody = response.getBody();

		if (httpStatus == 201 || httpStatus == 200) {
			var parsedResponse = JSON.parse(responseBody);
			var notes = httpStatus + ' ' + responseBody;

			currentRecord.work_notes = notes;

			var correlationId = parsedResponse.result.number;
			currentRecord.setValue('correlation_id', correlationId);
		}
	},

	// scripted rest api 'CreateOrUpdateAssetRequest'

	scriptedCreateUpdateAsset: function(requestBody) {

        var result = {};

        var assetRecord = new GlideRecord('x_2180885_it_ass_0_asset_request_table');
        assetRecord.addQuery('correlation_id', requestBody.correlation_id);
        assetRecord.setLimit(1);
        assetRecord.query();

        if (assetRecord.next()) {

            assetRecord.short_description = requestBody.short_description;
            assetRecord.description = requestBody.description;

            assetRecord.status = requestBody.status;
            assetRecord.priority = requestBody.priority;
            assetRecord.type_of_asset = requestBody.type_of_asset;
            assetRecord.consumables = requestBody.consumables;

            assetRecord.requestor = requestBody.requestor;
            assetRecord.assignment_group = requestBody.assignment_group;
            assetRecord.assigned_to = requestBody.assigned_to;
            assetRecord.company = requestBody.company;

            assetRecord.update();

            result.message = "Record updated successfully";
            result.number = assetRecord.getValue('number');
            result.sys_id = assetRecord.getUniqueValue();
            result.status_code = 200;

        } else {

            assetRecord.initialize();

            assetRecord.correlation_id = requestBody.correlation_id;
            assetRecord.short_description = requestBody.short_description;
            assetRecord.description = requestBody.description;

            assetRecord.status = requestBody.status;
            assetRecord.priority = requestBody.priority;
            assetRecord.type_of_asset = requestBody.type_of_asset;
            assetRecord.consumables = requestBody.consumables;

            assetRecord.requestor = requestBody.requestor;
            assetRecord.assignment_group = requestBody.assignment_group;
            assetRecord.assigned_to = requestBody.assigned_to;
            assetRecord.company = requestBody.company;

            var newSysId = assetRecord.insert();

            result.message = "Record created successfully";
            result.number = assetRecord.getValue('number');
            result.sys_id = newSysId;
            result.status_code = 201;
        }

        return result;
    },

	// Create Record Producer using Scripted REST API - 'CreateRecordProducer'

	createScriptedRPRequest: function(currentRecord) {

		var payload = {
			"correlation_id": currentRecord.getValue('number'),
			"short_description": currentRecord.getValue('short_description'),
			"description": currentRecord.getValue('description'),
			"requestor": currentRecord.getValue('requestor'),
			"assignment_group": currentRecord.getValue('assignment_group'),
			"assigned_to": currentRecord.getValue('assigned_to'),
			"company": currentRecord.getValue('company'),
			"status": currentRecord.getValue('status'),
			"priority": currentRecord.getValue('priority'),
			"type_of_asset": currentRecord.getValue('type_of_asset'),
			"consumables": currentRecord.getValue('consumables')
		};

		var jsonBody = JSON.stringify(payload);

		var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action',
			'Create Scripted RP Request'
		);

		r.setRequestHeader("Accept", "application/json");
		r.setRequestHeader("Content-Type", "application/json");
		r.setRequestBody(jsonBody);

		var response = r.executeAsync();
		var httpStatus = response.getStatusCode();
		var responseBody = response.getBody();

		gs.info('Asset requst :' + responseBody);

		if (httpStatus == 201) {
			var parsedResponse = JSON.parse(responseBody);

			var notes = httpStatus + ' ' + responseBody;

			currentRecord.work_notes = notes;

			var correlationId = parsedResponse.result.number;
			currentRecord.setValue('correlation_id', correlationId);
		}
	},

	// Scritped Rest API 'CreateRecordProducer'

	scriptedRecordProducer: function(requestBody) {

        var producerSysId = '1c4619c42f974390a94e2a7a6fa4e309';

        var cart = new sn_sc.CartJS();

        var item = {
            sysparm_id: producerSysId,
            sysparm_quantity: "1",
            variables: {
                correlation_id: requestBody.correlation_id,
                opened_by: requestBody.opened_by,
                requestor: requestBody.requestor,
                type_of_asset: requestBody.type_of_asset,
                consumables: requestBody.consumables,
                assignment_group: requestBody.assignment_group,
                assigned_to: requestBody.assigned_to,
                status: requestBody.status,
                priority: requestBody.priority,
                company: requestBody.company,
                short_description: requestBody.short_description,
                description: requestBody.description
            }
        };

        cart.addToCart(item);

        var cartResult = cart.checkoutCart();

		gs.info('IT Asset Request : ' + cartResult.request_id + '  ' + cartResult.error_message);

        gs.info('IT Asset - Cart Result: ' + JSON.stringify(cartResult));
        gs.info('IT Asset - Request Body: ' + JSON.stringify(requestBody));

        var gr = new GlideRecord('x_2180885_it_ass_0_asset_request_table');
        gr.addQuery('correlation_id', requestBody.correlation_id);
        gr.setLimit(1);
        gr.query();

        if (gr.next()) {

            var responseBody = {
                success: true,
                message: "Record Producer submitted successfully",
                number: gr.getValue('number')
            };

            responseBody.status_code = 201;

            gs.info('IT Asset - Response Body: ' + JSON.stringify(responseBody));

            return responseBody;
        }
    },

	// Send attachment using Attachment API

    sendAttachment: function(attachmentGr) {
        var parentGR = new GlideRecord('x_2180885_it_ass_0_asset_request_table');

        if (!parentGR.get(attachmentGr.table_sys_id)) {
            return;
        }

        var targetSysId = '';
        var grMap = new GlideRecord('x_2180885_it_ass_0_integration_map');
        grMap.addQuery('local_sys_id', parentGR.getUniqueValue());
        grMap.addQuery('target', 'Instance');
        grMap.setLimit(1);
        grMap.query();

        if (grMap.next()) {
            targetSysId = grMap.getValue('remote_sys_id');
        }

        if (targetSysId) {
			var r = new sn_ws.RESTMessageV2(
				'Instance-a Outbound Action', 
				'Send Attachment'
			);

			r.setRequestHeader("Content-Type", attachmentGr.getValue('content_type'));
			r.setRequestHeader("Accept", "application/json");

			r.setStringParameter('target_sys_id', targetSysId);
			r.setStringParameter('file_name', attachmentGr.getValue('file_name'));

			r.setRequestBodyFromAttachment(attachmentGr.getUniqueValue());

			var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var notes = httpStatus + ' ' + responseBody;
            parentGR.work_notes = notes;
            parentGR.update();

			var parsedResponse = JSON.parse(responseBody);

			var remoteAttachmentSysId = parsedResponse.result.sys_id;

			if (remoteAttachmentSysId) {

				var localAttachmentSysId = attachmentGr.getUniqueValue();

				var mapGr = new GlideRecord('x_2180885_it_ass_0_integration_map');
				mapGr.initialize();
				mapGr.setValue('local_sys_id', localAttachmentSysId);
				mapGr.setValue('remote_sys_id', remoteAttachmentSysId);
				mapGr.setValue('target', 'Attachment'); 
				mapGr.insert();

				// create mapping record on instnace B

				var mapRest = new sn_ws.RESTMessageV2(
					'Instance-a Outbound Action',
					'Create Integration Map Record'
				);

				var mapPayload = {
					"local_sys_id": remoteAttachmentSysId, 
					"remote_sys_id": attachmentGr.getUniqueValue(),
					"target": "Attachment"
				};

				mapRest.setRequestHeader("Accept", "application/json");
				mapRest.setRequestHeader("Content-Type", "application/json");
				mapRest.setRequestBody(JSON.stringify(mapPayload));

				mapRest.execute();
			}

			gs.info("status: " + httpStatus + "\nResponse Body: " + responseBody);
		}
    },

	// Delete Attachment using Attachment API

	deleteAttachment: function(localAttachmentSysId) {

		var mapGr = new GlideRecord('x_2180885_it_ass_0_integration_map');
		mapGr.addQuery('local_sys_id', localAttachmentSysId);
		mapGr.addQuery('target', 'Attachment');
		mapGr.setLimit(1);
		mapGr.query();

		if (mapGr.next()) {

			var remoteAttachmentSysId = mapGr.getValue('remote_sys_id');

			var r = new sn_ws.RESTMessageV2(
				'Instance-a Outbound Action',
				'Delete Attachment'
			);

			r.setStringParameterNoEscape('sys_id', remoteAttachmentSysId);

			// var response = r.execute();
			var response = r.executeAsync();
			var httpstatus = response.getStatusCode();

			if (httpstatus == 200 || httpstatus == 204) {
				mapGr.deleteRecord();
			} 

		}
	},

	// Order catalog item using Catalog API

	orderCatalogItem: function(currentRecord, catalogItemSysId) {
		var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action',
			'Order Catalog Item'
		);

		r.setStringParameter('catalog_item_sys_id', catalogItemSysId);

		r.setRequestHeader("Accept", "application/json");
        r.setRequestHeader("Content-Type", "application/json");

		var payload = {
			"sysparm_quantity": "1",
			"variables": {
				"remote_sys_id" : currentRecord.getUniqueValue(),
				"correlation_id": currentRecord.getValue('number'),
				"opened_by": currentRecord.getValue('opened_by'),
				"requestor": currentRecord.getValue('requestor'),
				"type_of_asset": currentRecord.getValue('type_of_asset'),
				"consumables": currentRecord.getValue('consumables'),
				"assignment_group": currentRecord.getValue('assignment_group'),
				"assigned_to": currentRecord.getValue('assigned_to'),
				"status": currentRecord.getValue('status'),
				"priority": currentRecord.getValue('priority'),
				"company": currentRecord.getValue('company'),
				"short_description": currentRecord.getValue('short_description'),
				"description": currentRecord.getValue('description')
			}
		};

		r.setRequestBody(JSON.stringify(payload));

		var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        var parsedResponse = JSON.parse(responseBody);


		if (httpStatus == 200) {
			var notes = httpStatus + ' ' + responseBody;
			currentRecord.work_notes = notes;
		}

		return null;
	},

	// Submit Record Producer using Catalog API

	submitRecordProducer: function(currentRecord, producerSysId) {
		var r = new sn_ws.RESTMessageV2(
			'Instance-a Outbound Action', 
			'Submit Record Producer'
		);

		r.setStringParameter('record_producer_sys_id', producerSysId);

		r.setRequestHeader("Accept", "application/json");
		r.setRequestHeader("Content-Type", "application/json");

		var payload = {
			"variables": {
				"correlation_id": currentRecord.getValue('number'),
				"requestor": currentRecord.getValue('requestor'),
				"type_of_asset": currentRecord.getValue('type_of_asset'),
				"consumables": currentRecord.getValue('consumables'),
				"assignment_group": currentRecord.getValue('assignment_group'),
				"assigned_to": currentRecord.getValue('assigned_to'),
				"status": currentRecord.getValue('status'),
				"priority": currentRecord.getValue('priority'),
				"company": currentRecord.getValue('company'),
				"short_description": currentRecord.getValue('short_description'),
				"description": currentRecord.getValue('description')
			}
		};

		r.setRequestBody(JSON.stringify(payload));

		var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        var parsedResponse = JSON.parse(responseBody);


		if (httpStatus == 200) {
			var notes = httpStatus + ' ' + responseBody;
			currentRecord.setValue('correlation_id', parsedResponse.result.number);
			currentRecord.work_notes = notes;
		}

		return null;
	},

	inboundFlowAction: function(emailbody, senderid) {

        var outputs = {};

        // ASSET TYPE
        var matchAsset = emailbody.match(/Asset Type:\s*(.+)/i);

        if (matchAsset && matchAsset[1]) {

            var asset = matchAsset[1].trim();

            if (asset === 'Computer') {
                outputs.asset_type = 'Computer';
            } else if (asset === 'Network Gear') {
                outputs.asset_type = 'Network Gear';
            } else if (asset === 'Printer') {
                outputs.asset_type = 'Printer';
            } else if (asset === 'UPS') {
                outputs.asset_type = 'UPS';
            }
        }

        // CONSUMABLE
        var matchConsumable = emailbody.match(/Consumables:\s*(.+)/i);

        if (matchConsumable && matchConsumable[1]) {
            outputs.consumable = matchConsumable[1]
                .trim()
                .toLowerCase()
                .replace(/\s+/g, '_');
        }

        // PRIORITY
        var matchPriority = emailbody.match(/Priority:\s*(.+)/i);

        if (matchPriority && matchPriority[1]) {
            outputs.priority = matchPriority[1].trim();
        } else {
            outputs.priority = '3';
        }

        // VIP CHECK
        if (senderid) {

            var grUser = new GlideRecord('sys_user');

            if (grUser.get(senderid)) {

                if (grUser.getValue('vip') == '1') {
                    outputs.priority = '1';
                }
            }
        }

        // ASSIGNMENT GROUP
        var groupName = '';

        if (outputs.asset_type === 'Computer') {
            groupName = 'Computers';
        } else if (outputs.asset_type === 'Network Gear') {
            groupName = 'Network Gear';
        } else if (outputs.asset_type === 'Printer') {
            groupName = 'Printers';
        } else if (outputs.asset_type === 'UPS') {
            groupName = 'UPS';
        }

        if (groupName) {

            var grGroup = new GlideRecord('sys_user_group');

            if (grGroup.get('name', groupName)) {
                outputs.assignment_group = grGroup.getUniqueValue();
            }
        }

        return outputs;
    },

    type: 'assetRequestUtils'
};
